def public_voice(links: list[dict], market: str) -> tuple[float, str] | None:
    """Customer voice for a market without BMW comments (e.g. China): linked, cited evidence that comes from that
    market's customers themselves — buyer-survey hypotheses (market_intel) and owner-rating gaps (public_review)."""
    items = []
    for f in links:
        if f["relation"] != "supports" or f["market_code"] != market:
            continue
        mt = json.loads(f["metrics_json"] or "{}")
        tiers = mt.get("tiers") or {}
        tw = max((TIER_W.get(t, 0.5) for t in tiers), default=0.5)
        if f["source_kind"] == "market_intel":
            items.append(STRENGTH_W.get(mt.get("strength"), 0.6) * tw)
        elif f["source_kind"] == "public_review" and f["type"] in ("owner_rating_gap", "owner_rating_strength"):
            items.append(0.8 * tw)
    if not items:
        return None
    val = PUBLIC_VOICE_DISCOUNT * min(1.0, sum(items) / 2)
    return val, (f"{len(items)} cited buyer-survey / owner-rating finding(s) from {market} customers stand in at "
                 f"×{PUBLIC_VOICE_DISCOUNT}")


